<?php
declare(strict_types=1);
trait MandateOperations {
    public function beginHolder(array $r):array{
        $this->staff(['admin','staff','finance']);$actor=$this->actor();$id=textField($r,'mandate_id',32);$m=$this->one('SELECT * FROM mandates WHERE id=?',[$id]);ensure($m&&$m['state']!=='REVOKED','Mandato no disponible.');$contract=$this->one('SELECT * FROM contracts WHERE id=?',[$m['contract_id']]);ensure($contract&&$contract['state']==='SIGNED','Contrato no disponible.');$snapshot=$this->open($contract['snapshot_enc']);$oldId=null;
        if(isset($r['bank'])){$reason=textField($r,'reason',600);ensure(strlen($reason)>=8,'Explica el cambio de cuenta (mínimo 8 caracteres).');ensure(!$this->one("SELECT id FROM dues WHERE mandate_id=? AND state IN ('EXPORTED','SENT')",[$id]),'Hay cuotas bancarias en curso. Resuélvelas antes de cambiar la cuenta.');$bank=validateBank($r['bank'],$snapshot['personal']);$oldId=$id;$id=uuid();$ref='TF-M-'.strtoupper(substr($id,0,20));$this->transaction(function()use($m,$bank,$id,$ref,$actor,$reason){$this->sql('INSERT INTO mandates(id,reference,member_id,contract_id,bank_enc,last_four,state,holder_same,replaces_id) VALUES(?,?,?,?,?,?,\'PENDING_HOLDER\',?,?)',[$id,$ref,$m['member_id'],$m['contract_id'],$this->seal($bank,'bank'),substr($bank['iban'],-4),(int)$bank['holder_same'],$m['id']]);$this->audit($actor,'BANK_CHANGE_REQUESTED',$id,['previous'=>$m['id'],'reason'=>$reason]);});$m=$this->one('SELECT * FROM mandates WHERE id=?',[$id]);}
        ensure($m['state']==='PENDING_HOLDER','El mandato ya está firmado.');$bank=$this->open($m['bank_enc'],'bank');$legal=$this->one('SELECT * FROM legal_versions WHERE brand=? AND active=1 ORDER BY created_at DESC LIMIT 1',[$snapshot['tariff']['brand']]);ensure($legal,'Faltan textos legales.');$snapshot['kind']='holder';$snapshot['reference']=$m['reference'];$snapshot['date_local']=date('d-m-Y H:i');$snapshot['prepared_at']=instant();$snapshot['bank']=$bank;$snapshot['legal']=$legal;$snapshot['mandate_reference']=$m['reference'];$snapshot['related_contract_reference']=$contract['reference'];$snapshot['related_pdf_hash']=$contract['pdf_hash'];$snapshot['mandate_id']=$id;$snapshot['personal']=['name'=>$snapshot['personal']['name'],'surname'=>$snapshot['personal']['surname']];
        if(($this->config['request_portal']??'')==='admin')return $this->issueTabletInvite(['kind'=>'holder','snapshot'=>$snapshot]);
        $_SESSION=['mode'=>'kiosk','kiosk_locked'=>true,'device_actor'=>$actor,'csrf'=>uuid(),'holder_mandate'=>$id,'last_activity'=>time()];session_regenerate_id(true);$draft=uuid();$hash=hash('sha256',jencode($snapshot));$this->sql('INSERT INTO drafts(id,session_hash,data_enc,review_enc,review_hash,expires_at,updated_at) VALUES(?,?,?,?,?,?,?)',[$draft,$this->sessionHash(),$this->seal(['type'=>'holder','mandate_id'=>$id]),$this->seal($snapshot),$hash,gmdate('Y-m-d\TH:i:s\Z',time()+1800),instant()]);$_SESSION['draft_id']=$draft;return ['holder'=>true,'review_hash'=>$hash,'name'=>$bank['holder'],'iban_masked'=>'•••• '.substr($bank['iban'],-4),'csrf'=>$_SESSION['csrf']];
    }
    public function signHolder(array $r):array{$this->kiosk();ensure(($r['confirmed']??false)===true,'Confirma la firma del titular.');$signature=validateSignature($r['signature']??null);return $this->transaction(function()use($r,$signature){$d=$this->draft();ensure($d['review_enc']&&hash_equals($d['review_hash'],(string)($r['review_hash']??'')),'Revisa el mandato de nuevo.',409);$s=$this->open($d['review_enc']);ensure(($s['kind']??'')==='holder'&&($_SESSION['holder_mandate']??'')===$s['mandate_id'],'No es una sesión de firma de titular.',403);$m=$this->one('SELECT * FROM mandates WHERE id=?',[$s['mandate_id']]);ensure($m&&$m['state']==='PENDING_HOLDER','Mandato no disponible.');if($m['replaces_id'])ensure(!$this->one("SELECT id FROM dues WHERE mandate_id=? AND state IN ('EXPORTED','SENT')",[$m['replaces_id']]),'Hay una exportación bancaria en curso. El centro debe revisarla.');$pdf=(new ContractPdf($this->root,$this->config))->build($s,$signature);$this->sql('INSERT INTO mandate_evidence VALUES(?,?,?,?,?,?,?)',[uuid(),$m['id'],$this->seal($s),$this->seal($signature,'signature'),$this->vault->encrypt($pdf,'pdf'),hash('sha256',$pdf),instant()]);if($m['replaces_id'])$this->sql("UPDATE mandates SET state='REVOKED',revoked_at=? WHERE id=?",[instant(),$m['replaces_id']]);$this->sql("UPDATE mandates SET state='ACTIVE',signed_at=? WHERE id=?",[instant(),$m['id']]);if($m['replaces_id']){$this->sql("UPDATE mandates SET state='REVOKED',revoked_at=? WHERE id=?",[instant(),$m['replaces_id']]);$this->sql("UPDATE dues SET mandate_id=?,revision=revision+1 WHERE mandate_id=? AND state='PREPARED'",[$m['id'],$m['replaces_id']]);}$this->audit($this->actor(),'HOLDER_MANDATE_SIGNED',$m['id'],['pdf_hash'=>hash('sha256',$pdf),'contract_hash'=>$s['related_pdf_hash']]);$this->sql('DELETE FROM drafts WHERE id=?',[$d['id']]);unset($_SESSION['draft_id'],$_SESSION['holder_mandate']);$_SESSION['receipt_mandate']=$m['id'];return ['id'=>$m['id'],'reference'=>$m['reference'],'holder'=>true];});}
    public function mandateDocument(string $id):string{if(($_SESSION['mode']??'')==='kiosk')ensure(($_SESSION['receipt_mandate']??'')===$id,'Documento no autorizado.',403);else $this->staff(['admin','staff','finance']);$r=$this->one('SELECT pdf_enc,pdf_hash FROM mandate_evidence WHERE mandate_id=?',[$id]);ensure($r,'No hay documento de titular firmado.',404);$pdf=$this->vault->decrypt($r['pdf_enc'],'pdf');ensure(hash_equals($r['pdf_hash'],hash('sha256',$pdf)),'Documento no íntegro.',500);$this->transaction(fn()=>$this->audit($this->actor(),'MANDATE_DOCUMENT_DOWNLOADED',$id));return $pdf;}
}
